update questions set prompt = 'A diferença fundamental entre codominância e dominância incompleta é que, na codominância:', options = array['Os dois produtos alélicos se expressam de modo reconhecível no heterozigoto', 'Os dois alelos geram um fenótipo intermediário entre os parentais', 'Um dos alelos é sempre completamente dominante sobre o outro', 'Não existe qualquer diferença entre os dois fenômenos'], explanation = 'Na codominância, os fenótipos aparecem lado a lado; na dominância incompleta, ocorre mistura em um fenótipo intermediário.'
