 where question_id = '98bd0ad2-8b11-418c-b087-b862fe1cd253' and locale = 'en';
update question_translations set prompt = 'La diferencia fundamental entre la codominancia y la dominancia incompleta es que, en la codominancia:', options = array['Ambos productos alélicos se expresan de forma reconocible en el heterocigoto', 'Los dos alelos generan un fenotipo intermedio entre los parentales', 'Uno de los alelos es siempre completamente dominante sobre el otro', 'No existe ninguna diferencia entre los dos fenómenos'], explanation = 'En la codominancia, los fenotipos aparecen uno junto al otro; en la dominancia incompleta, se mezclan en un fenotipo intermedio.'
 where question_id = '98bd0ad2-8b11-418c-b087-b862fe1cd253' and locale = 'es';

