update question_translations set prompt = 'Utilitarianism, by Jeremy Bentham and John Stuart Mill, considers an action right when it:', options = array['Conforms to a moral rule valid regardless of outcomes', 'Produces the greatest happiness for the greatest number of people', 'Is performed by a virtuous person regardless of the effect produced', 'Preserves individual liberty even when it reduces aggregate well-being'], explanation = 'Utilitarianism is consequentialist: it judges actions by their results in terms of general well-being.'
 where question_id = '5be1ac01-86fd-5673-874d-b79171e84376' and locale = 'en';
update question_translations set prompt = 'El utilitarismo, de Jeremy Bentham y John Stuart Mill, considera correcta una acción cuando:', options = array['Se ajusta a una regla moral válida independientemente de los resultados', 'Produce la mayor felicidad para el mayor número de personas', 'Es realizada por una persona virtuosa independientemente del efecto producido', 'Preserva la libertad individual aunque reduzca el bienestar agregado'], explanation = 'El utilitarismo es consecuencialista: juzga las acciones por sus resultados en términos de bienestar general.'
 where question_id = '5be1ac01-86fd-5673-874d-b79171e84376' and locale = 'es';

-- fisica: Magnetismo e Eletromagnetismo -- Melhoria de distratores: alternativas mais plausíveis e menos denunciadas por absolutos.
update questions set prompt = 'Um ímã, independentemente de seu tamanho, sempre possui:', options = array['Dois polos magnéticos (norte e sul), que não podem ser separados', 'Um polo predominante, definido pelo formato', 'Dois polos que podem ser isolados ao cortar o ímã', 'Um polo norte e uma região neutra no extremo oposto'], explanation = 'Todo ímã comum tem polos norte e sul; ao dividi-lo, cada pedaço vira um ímã menor, também com dois polos. Monopolos magnéticos isolados nunca foram observados.'
 where id = '018e8d33-dbea-4c22-b17e-9c28bf2580bc' and correct_index = 0;
update question_translations set prompt = 'A magnet, regardless of its size, always has:', options = array['Two magnetic poles (north and south), which cannot be separated', 'One predominant pole, determined by its shape', 'Two poles that can be isolated by cutting the magnet', 'A north pole and a neutral region at the opposite end'], explanation = 'Every ordinary magnet has a north and a south pole; when it is broken, each piece becomes a smaller magnet, also with two poles. Isolated magnetic monopoles have never been observed.'
 where question_id = '018e8d33-dbea-4c22-b17e-9c28bf2580bc' and locale = 'en';
update question_translations set prompt = 'Un imán, independientemente de su tamaño, siempre tiene:', options = array['Dos polos magnéticos (norte y sur), que no pueden separarse', 'Un polo predominante, definido por su forma', 'Dos polos que pueden aislarse al cortar el imán', 'Un polo norte y una región neutra en el extremo opuesto'], explanation = 'Todo imán común tiene polos norte y sur; al dividirlo, cada trozo se convierte en un imán más pequeño, también con dos polos. Nunca se han observado monopolos magnéticos aislados.'
 where question_id = '018e8d33-dbea-4c22-b17e-9c28bf2580bc' and locale = 'es';

