-- fisica: Termologia e Termodinâmica -- Melhoria de distratores: alternativas mais plausíveis e menos denunciadas por absolutos.
update questions set prompt = 'A Segunda Lei da Termodinâmica estabelece que, em um sistema isolado, a entropia (grau de desordem) tende a:', options = array['Aumentar ou, no máximo, permanecer constante ao longo do tempo', 'Diminuir até atingir necessariamente zero', 'Oscilar livremente, sem relação com irreversibilidade', 'Permanecer constante em qualquer transformação espontânea'], explanation = 'Pela Segunda Lei, em um sistema isolado a entropia não diminui: aumenta nos processos espontâneos e permanece constante apenas em um processo reversível ideal.'
 where id = 'b36783c6-ecb8-430c-8295-d3280916b119' and correct_index = 0;
update question_translations set prompt = 'The Second Law of Thermodynamics states that, in an isolated system, entropy (the degree of disorder) tends to:', options = array['Increase or, at most, stay constant over time', 'Decrease until necessarily reaching zero', 'Oscillate freely, unrelated to irreversibility', 'Remain constant in every spontaneous transformation'], explanation = 'By the Second Law, the entropy of an isolated system does not decrease: it increases in spontaneous processes and stays constant only in an ideal reversible process.'
 where question_id = 'b36783c6-ecb8-430c-8295-d3280916b119' and locale = 'en';
update question_translations set prompt = 'La Segunda Ley de la Termodinámica establece que, en un sistema aislado, la entropía (grado de desorden) tiende a:', options = array['Aumentar o, como máximo, permanecer constante a lo largo del tiempo', 'Disminuir hasta alcanzar necesariamente cero', 'Oscilar libremente, sin relación con la irreversibilidad', 'Permanecer constante en cualquier transformación espontánea'], explanation = 'Por la Segunda Ley, en un sistema aislado la entropía no disminuye: aumenta en los procesos espontáneos y solo permanece constante en un proceso reversible ideal.'
 where question_id = 'b36783c6-ecb8-430c-8295-d3280916b119' and locale = 'es';

