update question_translations set prompt = 'El foco principal de un espejo cóncavo es el punto donde:', options = array['Convergen los rayos de luz paralelos al eje principal, después de la reflexión', 'Los rayos paralelos se cruzan antes de la reflexión', 'Los rayos que pasan por el centro de curvatura cambian de dirección', 'Se encuentra el vértice geométrico del espejo'], explanation = 'En el espejo cóncavo, los rayos paralelos al eje principal convergen en el foco después de la reflexión.'
 where question_id = '2ada1a29-4b0c-4b6e-b49c-a3bd442c8c90' and locale = 'es';

