update question_translations set prompt = 'Respecto al objeto, una imagen puede clasificarse, según su orientación, como:', options = array['Derecha (mismo sentido que el objeto) o invertida (sentido opuesto)', 'Real o virtual, según pueda o no proyectarse', 'Mayor, menor o igual, según el tamaño', 'Convergente o divergente, según los rayos reflejados'], explanation = 'Según su orientación, la imagen puede ser derecha (coincidente con el objeto) o invertida respecto a él.'
