-- fisica: Óptica > Espelhos esféricos > Formação de imagens -- Melhoria de distratores: alternativas mais plausíveis e menos denunciadas por absolutos.
update questions set prompt = 'Uma imagem é classificada como virtual quando:', options = array['É formada pelo prolongamento imaginário dos raios de luz, sem encontro real', 'Os raios refletidos convergem fisicamente e podem ser projetados', 'Os raios refletidos convergem no centro de curvatura em qualquer situação', 'A imagem se forma no mesmo ponto ocupado pelo objeto'], explanation = 'Imagens virtuais surgem do prolongamento dos raios refletidos ou refratados, sem que eles realmente se cruzem.'
 where id = '8cfabfc2-0651-46d9-af70-76d349ca9010' and correct_index = 0;
update question_translations set prompt = 'An image is classified as virtual when:', options = array['It is formed by the imaginary extension of light rays, with no real meeting point', 'Reflected rays physically converge and can be projected', 'Reflected rays converge at the center of curvature in every situation', 'The image forms at the same point occupied by the object'], explanation = 'Virtual images arise from extending the reflected or refracted rays backward, without the rays actually crossing.'
 where question_id = '8cfabfc2-0651-46d9-af70-76d349ca9010' and locale = 'en';
update question_translations set prompt = 'Una imagen se clasifica como virtual cuando:', options = array['Se forma por la prolongación imaginaria de los rayos de luz, sin un encuentro real', 'Los rayos reflejados convergen físicamente y pueden proyectarse', 'Los rayos reflejados convergen en el centro de curvatura en cualquier situación', 'La imagen se forma en el mismo punto ocupado por el objeto'], explanation = 'Las imágenes virtuales surgen de la prolongación de los rayos reflejados o refractados, sin que estos realmente se crucen.'
 where question_id = '8cfabfc2-0651-46d9-af70-76d349ca9010' and locale = 'es';

