 where question_id = '1b8c4d26-c2ff-4b04-888e-1df78b459a78' and locale = 'en';
update question_translations set prompt = 'Uno de los rayos notables usados para construir imágenes en espejos esféricos afirma que todo rayo que incide paralelo al eje principal:', options = array['Se refleja pasando por el foco (espejo cóncavo) o parece venir del foco (espejo convexo)', 'Se refleja pasando por el centro de curvatura', 'Se refleja en el vértice sin obedecer la ley de la reflexión', 'Se refleja tangencialmente a la superficie del espejo'], explanation = 'Este es uno de los rayos notables fundamentales en la construcción geométrica de imágenes en espejos esféricos.'
 where question_id = '1b8c4d26-c2ff-4b04-888e-1df78b459a78' and locale = 'es';

