update questions set prompt = 'No poema "Autopsicografia", de Pessoa, os versos "O poeta é um fingidor. / Finge tão completamente / Que chega a fingir que é dor / A dor que deveras sente" sugerem que:', options = array['O poeta deve ocultar qualquer emoção pessoal do leitor', 'A experiência pessoal é reproduzida no poema sem transformação', 'A poesia registra sentimentos como um relato documental direto', 'A poesia transforma a emoção vivida em construção artística, que não coincide com a experiência bruta'], explanation = 'Para Pessoa, o poeta "finge" ao elaborar o sentimento pela linguagem; a arte é uma recriação da emoção.'
