update question_translations set prompt = 'In Pessoa''s poem "Autopsychography", the lines "The poet is a pretender. / He pretends so completely / That he even pretends to be pain / The pain he truly feels" suggest that:', options = array['The poet must hide every personal emotion from the reader', 'Personal experience is reproduced in the poem without transformation', 'Poetry records feelings as a direct documentary account', 'Poetry turns lived emotion into an artistic construction that does not coincide with raw experience'], explanation = 'For Pessoa, the poet "pretends" when working feeling through language; art is a re-creation of emotion.'
