update question_translations set prompt = 'En el poema "Autopsicografía", de Pessoa, los versos "El poeta es un fingidor. / Finge tan completamente / Que hasta finge que es dolor / El dolor que en verdad siente" sugieren que:', options = array['El poeta debe ocultar al lector toda emoción personal', 'La experiencia personal se reproduce en el poema sin transformación', 'La poesía registra los sentimientos como un relato documental directo', 'La poesía transforma la emoción vivida en construcción artística, que no coincide con la experiencia bruta'], explanation = 'Para Pessoa, el poeta "finge" al elaborar el sentimiento mediante el lenguaje; el arte es una recreación de la emoción.'
 where question_id = '2663e069-8696-5d3e-93ae-2f25c94d8067' and locale = 'es';

