update question_translations set prompt = '¿Qué caracteriza a un párrafo de desarrollo bien construido en una redacción argumentativa?', options = array['Presentar un argumento con repertorio sociocultural y una conclusión parcial vinculada a la tesis', 'Retomar la tesis con otras palabras sin desarrollar una razón adicional', 'Presentar ejemplos relacionados con el tema sin explicar su relación con el argumento', 'Reunir citas de autoridad sin relacionarlas con el punto defendido'], explanation = 'Un buen párrafo de desarrollo presenta un argumento consistente, sostenido por repertorio sociocultural y conectado a la tesis defendida.'
 where question_id = 'd7d6dcd1-2918-442a-a4a4-b4d8b8b1794a' and locale = 'es';

