update question_translations set prompt = 'Las fuerzas intermoleculares, responsables de mantener unidas las moléculas en los líquidos y sólidos moleculares, incluyen, entre otras:', options = array['Los puentes de hidrógeno, las interacciones dipolo-dipolo y las fuerzas de London (dipolo inducido)', 'Interacciones ion-dipolo y enlaces covalentes intramoleculares', 'Enlaces metálicos e interacciones núcleo-electrón', 'Enlaces covalentes apolares y enlaces iónicos intramoleculares'], explanation = 'Las fuerzas intermoleculares actúan entre moléculas distintas, a diferencia de los enlaces covalentes internos.'
