-- quimica: Soluções -- Melhoria de distratores: alternativas mais plausíveis e menos denunciadas por absolutos.
update questions set prompt = 'Uma solução é classificada como saturada quando:', options = array['Contém a quantidade máxima de soluto que pode ser dissolvida naquela temperatura', 'Contém menos soluto que o limite de solubilidade naquela temperatura', 'Apresenta soluto e solvente em proporções iguais em massa', 'Possui concentração superior ao limite de solubilidade sem precipitação'], explanation = 'Na saturação, a solução atinge o limite de solubilidade do soluto nas condições dadas. A temperatura é decisiva, e para gases a pressão também conta.'
 where id = 'ac8d8444-81c5-4ec6-acc2-126acaf2f4a3' and correct_index = 0;
update question_translations set prompt = 'A solution is classified as saturated when it:', options = array['Contains the maximum amount of solute that can dissolve at that temperature', 'Contains less solute than the solubility limit at that temperature', 'Contains equal masses of solute and solvent', 'Has a concentration above the solubility limit without precipitation'], explanation = 'At saturation, the solution reaches the solubility limit of the solute under the given conditions. Temperature is decisive, and for gases pressure matters too.'
 where question_id = 'ac8d8444-81c5-4ec6-acc2-126acaf2f4a3' and locale = 'en';
update question_translations set prompt = 'Una solución se clasifica como saturada cuando:', options = array['Contiene la cantidad máxima de soluto que puede disolverse a esa temperatura', 'Contiene menos soluto que el límite de solubilidad a esa temperatura', 'Presenta soluto y disolvente en masas iguales', 'Posee una concentración superior al límite de solubilidad sin precipitación'], explanation = 'En la saturación, la solución alcanza el límite de solubilidad del soluto en las condiciones dadas. La temperatura es decisiva, y para los gases la presión también cuenta.'
 where question_id = 'ac8d8444-81c5-4ec6-acc2-126acaf2f4a3' and locale = 'es';

