update question_translations set prompt = 'The "myth of racial democracy" in Brazil is the idea that:', options = array['Legal equality would have eliminated economic differences among racial groups', 'Miscegenation would have prevented the formation of racial identities in the country', 'Racial mixing would have produced harmonious coexistence without racism, which hides real inequalities', 'Abolition would have immediately produced equal opportunities between White and Black people'], explanation = 'Florestan Fernandes, among others, showed that this idea masked discrimination and racial inequality.'
