-- sociologia: Introdução à sociologia > Senso comum e imaginação sociológica -- Equilibrar alternativa correta.; Melhoria de distratores: alternativas mais plausíveis e menos denunciadas por absolutos.
update questions set prompt = 'Ao estudar a sociedade de que faz parte, o sociólogo enfrenta o desafio do "estranhamento", que consiste em:', options = array['Tomar distância do familiar para transformá-lo em objeto de investigação', 'Evitar qualquer contato com as pessoas pesquisadas', 'Priorizar comparações com sociedades estrangeiras para evitar vieses locais', 'Rejeitar toda teoria prévia'], explanation = 'Estranhar o familiar permite questionar o que parece óbvio no próprio cotidiano.'
 where id = '6fe320af-741f-5619-a89c-1bd1c0715854' and correct_index = 0;
update question_translations set prompt = 'When studying the society they belong to, the sociologist faces the challenge of "estrangement", which consists in:', options = array['Take distance from the familiar and turn it into an object of investigation', 'Avoiding any contact with the people studied', 'Prioritize comparisons with foreign societies to avoid local biases', 'Rejecting all prior theory'], explanation = 'Making the familiar strange makes it possible to question what seems obvious in one''s own daily life.'
 where question_id = '6fe320af-741f-5619-a89c-1bd1c0715854' and locale = 'en';
update question_translations set prompt = 'Al estudiar la sociedad de la que forma parte, el sociólogo enfrenta el desafío del "extrañamiento", que consiste en:', options = array['Tomar distancia de lo familiar para convertirlo en objeto de investigación', 'Evitar cualquier contacto con las personas investigadas', 'Priorizar comparaciones con sociedades extranjeras para evitar sesgos locales', 'Rechazar toda teoría previa'], explanation = 'Extrañar lo familiar permite cuestionar lo que parece obvio en la propia vida cotidiana.'
 where question_id = '6fe320af-741f-5619-a89c-1bd1c0715854' and locale = 'es';

