update question_translations set prompt = 'Auguste Comte''s positivism argued that society should be studied:', options = array['With systematic observational methods inspired by the natural sciences', 'Through theological interpretations taken as the main form of social explanation', 'Only through artists'' intuition', 'With no concern for observable facts'], explanation = 'Comte saw positive science as the most advanced stage of knowledge; the Brazilian flag''s motto "Order and Progress" comes from positivism.'
 where question_id = '74a03227-5975-5fe8-bb1a-45a1baf2a746' and locale = 'en';
