-- sociologia: Poder, Estado e política > Estado e poder -- Melhoria de distratores: alternativas mais plausíveis e menos denunciadas por absolutos.
update questions set prompt = 'O conceito de "hegemonia", de Antonio Gramsci, explica que a dominação de uma classe se mantém:', options = array['Pela coerção física exercida diretamente pelo aparelho militar', 'Também pelo consenso, difundido pela cultura, escola, mídia e religião', 'Pelo controle econômico, sem necessidade de construir legitimidade social', 'Por acordos jurídicos entre classes, sem participação de instituições culturais'], explanation = 'Para Gramsci, a classe dirigente conquista a adesão dos dominados por meio de valores tidos como "senso comum".'
 where id = '64a1bbad-576c-5eff-a6d8-5880e705b9e7' and correct_index = 1;
update question_translations set prompt = 'Antonio Gramsci''s concept of "hegemony" explains that a class''s domination is maintained:', options = array['Through physical coercion exercised directly by the military apparatus', 'Also by consent, spread through culture, school, media and religion', 'Through economic control, without the need to build social legitimacy', 'Through legal agreements between classes, without cultural institutions'], explanation = 'For Gramsci, the ruling class wins the adherence of the dominated through values taken as "common sense".'
 where question_id = '64a1bbad-576c-5eff-a6d8-5880e705b9e7' and locale = 'en';
update question_translations set prompt = 'El concepto de "hegemonía", de Antonio Gramsci, explica que la dominación de una clase se mantiene:', options = array['Mediante la coerción física ejercida directamente por el aparato militar', 'También por el consenso, difundido por la cultura, la escuela, los medios y la religión', 'Mediante el control económico, sin necesidad de construir legitimidad social', 'Mediante acuerdos jurídicos entre clases, sin participación de instituciones culturales'], explanation = 'Para Gramsci, la clase dirigente conquista la adhesión de los dominados mediante valores tenidos por "sentido común".'
 where question_id = '64a1bbad-576c-5eff-a6d8-5880e705b9e7' and locale = 'es';

