update question_translations set prompt = 'Para Max Weber, el Estado moderno se define por poseer:', options = array['El control directo de la mayoría de las empresas estratégicas', 'La autoridad para definir la doctrina religiosa de la población', 'La propiedad jurídica del territorio y de los bienes de sus habitantes', 'El monopolio del uso legítimo de la fuerza física en un territorio'], explanation = 'Solo el Estado puede usar la fuerza de modo legítimo, dentro de reglas legales, en su territorio.'
 where question_id = '811cb321-5081-5128-905f-ea21a5943d5d' and locale = 'es';

